32d664e Fix an out-of-bound read caused by a wrong computation in hoedown's parse_fencedcode.
 src/document.c | 2 +-
 1 file changed, 1 insertion(+), 1 deletion(-)
commit 32d664e65347f19ef84d4e007fe572f572cb3f18
Author: Jonas Wagner <jbw@google.com>
Date:   Wed May 2 17:22:21 2018 +0200

    Fix an out-of-bound read caused by a wrong computation in hoedown's parse_fencedcode.

    This bug was detected by the Google Autofuzz project.

diff --git a/src/document.c b/src/document.c
index be3b1ab..cf55e28 100644
--- a/src/document.c
+++ b/src/document.c
@@ -2253,7 +2253,7 @@ parse_fencedcode(hoedown_buffer *ob, hoedown_document *doc, uint8_t *data, size_
                        is_empty(data + (line_start+w), i - (line_start+w)))
                        break;

-               i++;
+               if (i < size) i++;
        }

        text.data = data + text_start;
  2258
  2259          text.data = data + text_start;
  2260          text.size = line_start - text_start;
  2261
  2262          if (doc->md.blockcode) {
  2263                  doc->fencedcode_char = chr;
  2264                  doc->md.blockcode(ob, text.size ? &text : NULL, lang.size ? &lang : NULL, attr->size ? attr : NULL, &doc->data);
  2265                  doc->fencedcode_char = 0;
  2266          }
  2267
  2268          popbuf(doc, BUFFER_ATTRIBUTE);
  2269
  2270          return i;
  2271  }
  2272
  2273  static size_t
  2274  parse_blockcode(hoedown_buffer *ob, hoedown_document *doc, uint8_t *data, size_t size)
  2275  {
  2276          size_t beg, end, pre;
  2277          hoedown_buffer *work = 0;
  2278          hoedown_buffer attr = { 0, 0, 0, 0, NULL, NULL, NULL };
  2279
  2280          work = newbuf(doc, BUFFER_BLOCK);
  2281
  2282          beg = 0;
  2283          while (beg < size) {
  2284                  for (end = beg + 1; end < size && data[end - 1] != '\n'; end++) {};
  2285                  pre = prefix_code(data + beg, end - beg);
  2286
  2287                  if (pre)
  2288                          beg += pre; /* skipping prefix */
  2289                  else if (!is_empty(data + beg, end - beg))
  2290                          /* non-empty non-prefixed line breaks the pre */
  2291                          break;
  2292
  2293                  if (beg < end) {
  2294                          /* verbatim copy to the working buffer,
  2295                                  escaping entities */
  2296                          if (is_empty(data + beg, end - beg))
  2297                                  hoedown_buffer_putc(work, '\n');
  2298                          else hoedown_buffer_put(work, data + beg, end - beg);
  2299                  }
  2300                  beg = end;
  2301          }
  2302
  2303          while (work->size && work->data[work->size - 1] == '\n')
  2304                  work->size -= 1;
  2305
  2306          if (doc->ext_flags & HOEDOWN_EXT_SPECIAL_ATTRIBUTE) {
  2307                  work->size = parse_attributes(work->data, work->size, NULL, &attr, "", 0, 0, doc->attr_activation);
  2308          }
  2309
  2310          hoedown_buffer_putc(work, '\n');
